pub async fn account_storage_bytes(
    pool: &SqlitePool,
    account_did: &str,
) -> Result<i64, sqlx::Error> {
    let row: (i64,) = sqlx::query_as(
        "SELECT COALESCE(SUM(b.size_bytes), 0) FROM blob_owners o \
         JOIN blobs b ON b.cid = o.cid WHERE o.account_did = ?",
    )
