) -> Result<(i64, i64), sqlx::Error> {
    let row: (i64, i64) = sqlx::query_as(
        "SELECT COUNT(*), COALESCE(SUM(b.size_bytes), 0) FROM blob_owners o \
         JOIN blobs b ON b.cid = o.cid WHERE o.account_did = ?",
