    pool: &SqlitePool,
    account_did: &str,
) -> Result<Option<(String, i64)>, sqlx::Error> {
    sqlx::query_as(
        "SELECT b.cid, b.size_bytes FROM blob_owners o \
         JOIN blobs b ON b.cid = o.cid WHERE o.account_did = ? \
         ORDER BY b.size_bytes DESC, b.cid ASC LIMIT 1",
    )
    .bind(account_did)
    .fetch_optional(pool)
    .await
}

